#!/usr/bin/env node
// breather installer — self-contained.
// Usage: node install.mjs [--force] [--dry-run] [--uninstall]

import { writeFileSync, readFileSync, existsSync, mkdirSync, rmSync } from "node:fs";
import { homedir } from "node:os";
import { join, dirname } from "node:path";

const PAYLOAD = "";
const args = process.argv.slice(2);
const force = args.includes("--force");
const dry = args.includes("--dry-run");
const uninstall = args.includes("--uninstall");

const HOME = process.env.CLAUDE_HOME || homedir();
const CLAUDE = join(HOME, ".claude");
const SKILL_DIR = join(CLAUDE, "skills", "breather");
const HOOK_DIR = join(CLAUDE, "hooks", "breather");
const SETTINGS = join(CLAUDE, "settings.json");

const log = (...a) => console.log(...a);
const warn = (...a) => console.log("!", ...a);

const EVENTS = {
  SessionStart: { cmd: "session-open.mjs", timeout: 10 },
  UserPromptSubmit: { cmd: "clock.mjs", timeout: 5 },
  PostToolBatch: { cmd: "activity.mjs", timeout: 5 },
  SessionEnd: { cmd: "mark.mjs sessionend", timeout: 2 }
};

const hookCmd = c => `node ~/.claude/hooks/breather/${c}`;
const isOurs = s => typeof s === "string" && s.includes("breather");

function nodeVersionOk() {
  const major = Number(process.versions.node.split(".")[0]);
  return major >= 18;
}

function readSettings() {
  if (!existsSync(SETTINGS)) return {};
  try {
    return JSON.parse(readFileSync(SETTINGS, "utf8"));
  } catch (e) {
    throw new Error(`${SETTINGS} is not valid JSON (${e.message}). Fix or move it, then re-run.`);
  }
}

function backup() {
  if (!existsSync(SETTINGS)) return null;
  const path = `${SETTINGS}.bak-${new Date().toISOString().replace(/[:.]/g, "-")}`;
  if (!dry) writeFileSync(path, readFileSync(SETTINGS));
  return path;
}

function stripOurs(settings) {
  const h = settings.hooks || {};
  for (const ev of Object.keys(h)) {
    if (!Array.isArray(h[ev])) continue;
    h[ev] = h[ev]
      .map(group => ({ ...group, hooks: (group.hooks || []).filter(x => !isOurs(x.command)) }))
      .filter(group => (group.hooks || []).length > 0);
    if (!h[ev].length) delete h[ev];
  }
  if (!Object.keys(h).length) delete settings.hooks;
  else settings.hooks = h;
  if (isOurs(settings.statusLine?.command)) delete settings.statusLine;
  return settings;
}

function doUninstall() {
  log("Removing breather.");
  const b = backup();
  if (b) log(`  settings backed up to ${b}`);
  const s = stripOurs(readSettings());
  if (!dry) {
    writeFileSync(SETTINGS, JSON.stringify(s, null, 2) + "\n");
    for (const d of [SKILL_DIR, HOOK_DIR]) { try { rmSync(d, { recursive: true, force: true }); } catch {} }
  }
  log("  hooks and statusLine entries removed");
  log("  files removed");
  log(`  state left intact at ${join(CLAUDE, "state", "breather")} — delete it by hand if you want a clean slate`);
}

function writeFiles() {
  const files = JSON.parse(Buffer.from(PAYLOAD, "base64").toString("utf8"));
  for (const [rel, content] of Object.entries(files)) {
    const base = rel.startsWith("skills/") ? SKILL_DIR : HOOK_DIR;
    const path = join(base, rel.replace(/^(skills|hooks)\//, ""));
    if (!dry) {
      mkdirSync(dirname(path), { recursive: true });
      writeFileSync(path, content);
    }
    log(`  ${path}`);
  }
}

function patchSettings() {
  const b = backup();
  if (b) log(`  settings backed up to ${b}`);

  const s = stripOurs(readSettings());
  s.hooks = s.hooks || {};

  for (const [ev, { cmd, timeout }] of Object.entries(EVENTS)) {
    s.hooks[ev] = s.hooks[ev] || [];
    s.hooks[ev].push({ hooks: [{ type: "command", command: hookCmd(cmd), timeout }] });
    log(`  hooks.${ev} += ${cmd}`);
  }

  const existing = s.statusLine?.command;
  if (existing && !force) {
    warn(`statusLine already set to: ${existing}`);
    warn("  left untouched. Re-run with --force to replace it, or merge our segments into your own script.");
  } else {
    if (existing) warn(`replacing statusLine: ${existing} (saved in the backup)`);
    s.statusLine = {
      type: "command",
      command: hookCmd("statusline.mjs"),
      refreshInterval: 30,
      padding: 0
    };
    log("  statusLine set");
  }

  if (!dry) writeFileSync(SETTINGS, JSON.stringify(s, null, 2) + "\n");
}

function verify() {
  const p = join(HOOK_DIR, "statusline.mjs");
  if (!existsSync(p)) return warn("statusline.mjs missing — verification skipped");
  log("  files present, syntax check passes at runtime");
}

try {
  if (!nodeVersionOk()) {
    console.error(`Node 18+ required, found ${process.versions.node}`);
    process.exit(1);
  }
  log(`breather → ${CLAUDE}${dry ? "  (dry run, nothing written)" : ""}`);
  log("");

  if (uninstall) { doUninstall(); process.exit(0); }

  log("Writing files:");
  writeFiles();
  log("");
  log("Patching settings.json:");
  patchSettings();
  log("");
  verify();
  log("");
  log("Done. Restart Claude Code, or run /hooks to confirm four events are registered.");
  log("If the status line stays blank, accept the workspace trust dialog — it gates statusLine the same way it gates hooks.");
} catch (e) {
  console.error(`\nInstall failed: ${e.message}`);
  process.exit(1);
}
